/** First lines of every generated binding module. */
export const header =
  '// Generated by scripts/bindings/generate.mjs from the custom elements manifest. Do not edit.';

/**
 * Type-only namespace imports for the named types event types reference, one per declaring
 * module (`import type * as foundationEvents from '../foundation/events.js'`). Qualifying each
 * name with its module keeps library types apart from platform types of the same name (the drag
 * and drop `DragEvent` and the DOM's).
 */
export function typeImports(references, relative) {
  const modules = [...new Set(references.map((reference) => reference.module))].sort();
  const namespaces = new Map(
    modules.map((module) => [
      module,
      module
        .replace(/^src\//u, '')
        .replace(/\.ts$/u, '')
        .split(/[/.-]/u)
        .filter(Boolean)
        .map((word, index) => (index ? word[0].toUpperCase() + word.slice(1) : word))
        .join(''),
    ]),
  );
  const alias = new Map(
    references.map((reference) => [
      `${reference.module}#${reference.name}`,
      `${namespaces.get(reference.module)}.${reference.name}`,
    ]),
  );
  return {
    imports: modules.map(
      (module) => `import type * as ${namespaces.get(module)} from '${relative(module)}';`,
    ),
    alias,
  };
}

/**
 * A manifest type's text with each referenced name qualified by its module namespace. A name is
 * replaced as a whole identifier, never as a property key (`item: TpMenuItem` keeps `item`).
 */
export function qualifiedType(type, alias) {
  // `{}` (any non-nullish value) is written as its lint-clean equivalent.
  let text = type.text.replace(/(?<![\w$])\{\}/gu, 'NonNullable<unknown>');
  for (const reference of type.references ?? []) {
    const qualified = alias.get(`${reference.module}#${reference.name}`);
    if (!qualified) continue;
    text = text.replace(
      new RegExp(`(?<![\\w$.'"])${reference.name}(?![\\w$])(?!\\??:)`, 'gu'),
      qualified,
    );
  }
  return text;
}
